import { Injectable, signal } from '@angular/core';

// STUB — bản lab không gọi backend thật. User mock có đủ mọi permission
// (Permissions: ['*'] + has() luôn true) để menu/submenu hiện đầy đủ khi tinh chỉnh UI.
export interface CurrentUser {
  Id: string;
  Email: string;
  DisplayName: string;
  ProfileId: string | null;
  Roles: string[];
  Permissions: string[];
}

const MOCK_USER: CurrentUser = {
  Id: 'mock-user',
  Email: 'demo@vnresource.vn',
  DisplayName: 'Nguyễn Minh Tuấn',
  ProfileId: null,
  Roles: ['Admin'],
  Permissions: ['*'],
};

@Injectable({ providedIn: 'root' })
export class CurrentUserService {
  private readonly _user = signal<CurrentUser | null>(MOCK_USER);
  readonly user = this._user.asReadonly();

  has(_permission: string): boolean {
    return true;
  }

  getActiveUserId(): string | null {
    return MOCK_USER.Id;
  }

  setActiveUserId(_id: string): void {
    /* no-op trong lab */
  }

  clearActiveUser(): void {
    this._user.set(null);
  }

  async load(): Promise<void> {
    this._user.set(MOCK_USER);
  }
}
