import {
  Component, ElementRef, HostListener, Injectable, computed, effect, inject, input, signal, viewChild,
} from '@angular/core';
import { TablerIconComponent } from '@tabler/icons-angular';
import { CurrentUserService } from '../core/auth/current-user.service';

/** 1 lệnh trong hộp tìm lệnh. perm = permission string (bỏ trống = ai cũng thấy). */
export interface HrmCommand {
  key: string;
  label: string;
  /** Icon Tabler (object mode). */
  icon?: unknown;
  /** Nhóm hiển thị (tiêu đề mờ phía trên cụm lệnh) — bên gọi cấp (i18n). */
  group?: string;
  perm?: string;
  action: () => void;
}

/** Service điều khiển hộp tìm lệnh: đăng ký lệnh + mở/đóng. Component đặt 1 lần ở shell. */
@Injectable({ providedIn: 'root' })
export class HrmCommandPaletteService {
  readonly visible = signal(false);
  private readonly _commands = signal<HrmCommand[]>([]);
  readonly commands = this._commands.asReadonly();

  /** Đăng ký (cộng dồn theo key — key trùng thì ghi đè). */
  register(cmds: HrmCommand[]): void {
    const map = new Map(this._commands().map((c) => [c.key, c]));
    for (const c of cmds) map.set(c.key, c);
    this._commands.set([...map.values()]);
  }
  unregister(keys: string[]): void {
    const drop = new Set(keys);
    this._commands.update((list) => list.filter((c) => !drop.has(c.key)));
  }
  open(): void { this.visible.set(true); }
  close(): void { this.visible.set(false); }
  toggle(): void { this.visible.update((v) => !v); }
}

/** hrm-command-palette — hộp tìm lệnh nhanh (Ctrl/⌘+K): gõ để lọc, ↑↓ chọn, Enter chạy,
 *  Esc đóng. Lệnh có perm chỉ hiện khi user có quyền (CurrentUserService). Đặt 1 lần ở shell.
 *  i18n-clean: placeholder/emptyText bên gọi cấp. */
@Component({
  selector: 'hrm-command-palette',
  imports: [TablerIconComponent],
  template: `
    @if (svc.visible()) {
      <div class="cp-mask" (click)="svc.close()"></div>
      <div class="cp-box" role="dialog" aria-modal="true">
        <input #inp class="cp-input" type="text"
          [placeholder]="placeholder()"
          [value]="query()"
          (input)="onQuery($event)"
          (keydown)="onKey($event)" />
        <div class="cp-list" role="listbox">
          @for (c of filtered(); track c.key; let i = $index) {
            @if (c.group && (i === 0 || filtered()[i - 1].group !== c.group)) {
              <div class="cp-group">{{ c.group }}</div>
            }
            <button type="button" class="cp-item" role="option"
              [class.is-active]="i === activeIdx()"
              [attr.aria-selected]="i === activeIdx()"
              (mouseenter)="activeIdx.set(i)"
              (click)="run(c)">
              @if (c.icon) { <tabler-icon class="cp-ic" [icon]="$any(c.icon)" [size]="16" /> }
              <span class="cp-label">{{ c.label }}</span>
            </button>
          } @empty {
            <div class="cp-empty">{{ emptyText() }}</div>
          }
        </div>
      </div>
    }
  `,
  host: { class: 'hrm-command-palette' },
  styles: [`
.cp-mask { position: fixed; inset: 0; background: var(--overlay, rgba(0,0,0,.45)); z-index: var(--z-modal, 1000); }
.cp-box {
  position: fixed; left: 50%; top: 18vh; transform: translateX(-50%);
  width: min(560px, calc(100vw - 32px)); z-index: calc(var(--z-modal, 1000) + 1);
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-lg);
  overflow: hidden; display: flex; flex-direction: column;
}
.cp-input {
  border: 0; outline: none; background: transparent; color: var(--text-strong);
  font-family: var(--font-sans); font-size: var(--fs-15); padding: 14px 16px;
  border-bottom: 1px solid var(--border-soft);
}
.cp-input::placeholder { color: var(--text-disabled); }
.cp-list { max-height: 320px; overflow-y: auto; padding: 6px; }
.cp-group { font-size: var(--fs-11); font-weight: 600; text-transform: uppercase; letter-spacing: .04em;
  color: var(--text-sub); padding: 8px 10px 4px; }
.cp-item {
  display: flex; align-items: center; gap: 10px; width: 100%;
  border: 0; background: transparent; cursor: pointer; text-align: left;
  padding: 8px 10px; border-radius: var(--radius-md);
  font-family: var(--font-sans); font-size: var(--fs-14); color: var(--text-body);
}
.cp-item.is-active { background: var(--primary-bg-subtle); color: var(--text-strong); }
.cp-ic { display: inline-flex; color: var(--icon-secondary); flex: none; }
.cp-label { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cp-empty { padding: 20px 12px; text-align: center; font-size: var(--fs-13); color: var(--text-sub); }
  `],
})
export class HrmCommandPalette {
  protected readonly svc = inject(HrmCommandPaletteService);
  private readonly user = inject(CurrentUserService);

  /** Placeholder ô tìm + chữ khi không có kết quả — bên gọi cấp (i18n). */
  readonly placeholder = input('');
  readonly emptyText = input('');
  /** Bật phím tắt Ctrl/⌘+K (tắt nếu shell muốn tự xử lý phím). */
  readonly hotkey = input(true);

  protected readonly query = signal('');
  protected readonly activeIdx = signal(0);
  private readonly inp = viewChild<ElementRef<HTMLInputElement>>('inp');

  /** Lọc theo quyền + từ khoá (không phân biệt hoa thường). */
  protected readonly filtered = computed(() => {
    const q = this.query().trim().toLowerCase();
    return this.svc.commands()
      .filter((c) => !c.perm || this.user.has(c.perm))
      .filter((c) => !q || c.label.toLowerCase().includes(q));
  });

  constructor() {
    // Mở → reset + focus ô tìm.
    effect(() => {
      if (this.svc.visible()) {
        this.query.set('');
        this.activeIdx.set(0);
        setTimeout(() => this.inp()?.nativeElement.focus());
      }
    });
  }

  @HostListener('document:keydown', ['$event'])
  onDocKey(e: KeyboardEvent): void {
    if (this.hotkey() && (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      this.svc.toggle();
    } else if (e.key === 'Escape' && this.svc.visible()) {
      this.svc.close();
    }
  }

  protected onQuery(e: Event): void {
    this.query.set((e.target as HTMLInputElement).value);
    this.activeIdx.set(0);
  }

  protected onKey(e: KeyboardEvent): void {
    const n = this.filtered().length;
    if (e.key === 'ArrowDown') { e.preventDefault(); this.activeIdx.update((i) => (i + 1) % Math.max(n, 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); this.activeIdx.update((i) => (i - 1 + Math.max(n, 1)) % Math.max(n, 1)); }
    else if (e.key === 'Enter') {
      const c = this.filtered()[this.activeIdx()];
      if (c) this.run(c);
    }
  }

  protected run(c: HrmCommand): void {
    this.svc.close();
    c.action();
  }
}
